648	    private long partitionReady(MetadataSnapshot metadataSnapshot, long nowMs, String topic,
649	                                TopicInfo topicInfo,
650	                                long nextReadyCheckDelayMs, Set<Node> readyNodes, Set<String> unknownLeaderTopics) {
651	        ConcurrentMap<Integer, Deque<ProducerBatch>> batches = topicInfo.batches;
652	        // Collect the queue sizes for available partitions to be used in adaptive partitioning.
653	        int[] queueSizes = null;
654	        int[] partitionIds = null;
655	        if (enableAdaptivePartitioning && batches.size() >= metadataSnapshot.cluster().partitionsForTopic(topic).size()) {
656	            // We don't do adaptive partitioning until we scheduled at least a batch for all
657	            // partitions (i.e. we have the corresponding entries in the batches map), we just
658	            // do uniform.  The reason is that we build queue sizes from the batches map,
659	            // and if an entry is missing in the batches map, then adaptive partitioning logic
660	            // won't know about it and won't switch to it.
661	            queueSizes = new int[batches.size()];
662	            partitionIds = new int[queueSizes.length];
663	        }
664	
665	        int queueSizesIndex = -1;
666	        boolean exhausted = this.free.queued() > 0;
667	        for (Map.Entry<Integer, Deque<ProducerBatch>> entry : batches.entrySet()) {
668	            TopicPartition part = new TopicPartition(topic, entry.getKey());
669	            // Advance queueSizesIndex so that we properly index available
670	            // partitions.  Do it here so that it's done for all code paths.
671	
672	            Node leader = metadataSnapshot.cluster().leaderFor(part);
673	            if (leader != null && queueSizes != null) {
674	                ++queueSizesIndex;
675	                assert queueSizesIndex < queueSizes.length;
676	                partitionIds[queueSizesIndex] = part.partition();
677	            }
678	
679	            Deque<ProducerBatch> deque = entry.getValue();
680	
681	            final long waitedTimeMs;
682	            final boolean backingOff;
683	            final int backoffAttempts;
684	            final int dequeSize;
685	            final boolean full;
686	
687	            OptionalInt leaderEpoch = metadataSnapshot.leaderEpochFor(part);
688	
689	            // This loop is especially hot with large partition counts. So -
690	
691	            // 1. We should avoid code that increases synchronization between application thread calling
692	            // send(), and background thread running runOnce(), see https://issues.apache.org/jira/browse/KAFKA-16226
693	
694	            // 2. We are careful to only perform the minimum required inside the
695	            // synchronized block, as this lock is also used to synchronize producer threads
696	            // attempting to append() to a partition/batch.
697	
698	            synchronized (deque) {
699	                // Deques are often empty in this path, esp with large partition counts,
700	                // so we exit early if we can.
701	                ProducerBatch batch = deque.peekFirst();
702	                if (batch == null) {
703	                    continue;
704	                }
705	
706	                waitedTimeMs = batch.waitedTimeMs(nowMs);
707	                batch.maybeUpdateLeaderEpoch(leaderEpoch);
708	                backingOff = shouldBackoff(batch.hasLeaderChangedForTheOngoingRetry(), batch, waitedTimeMs);
709	                backoffAttempts = batch.attempts();
710	                dequeSize = deque.size();
711	                full = dequeSize > 1 || batch.isFull();
712	            }
713	
714	            if (leader == null) {
715	                // This is a partition for which leader is not known, but messages are available to send.
716	                // Note that entries are currently not removed from batches when deque is empty.
717	                unknownLeaderTopics.add(part.topic());
718	            } else {
719	                if (queueSizes != null)
720	                    queueSizes[queueSizesIndex] = dequeSize;
721	                if (partitionAvailabilityTimeoutMs > 0) {
722	                    // Check if we want to exclude the partition from the list of available partitions
723	                    // if the broker hasn't responded for some time.
724	                    NodeLatencyStats nodeLatencyStats = nodeStats.get(leader.id());
725	                    if (nodeLatencyStats != null) {
726	                        // NOTE: there is no synchronization between reading metrics,
727	                        // so we read ready time first to avoid accidentally marking partition
728	                        // unavailable if we read while the metrics are being updated.
729	                        long readyTimeMs = nodeLatencyStats.readyTimeMs;
730	                        if (readyTimeMs - nodeLatencyStats.drainTimeMs > partitionAvailabilityTimeoutMs)
731	                            --queueSizesIndex;
732	                    }
733	                }
734	
735	                nextReadyCheckDelayMs = batchReady(exhausted, part, leader, waitedTimeMs, backingOff,
736	                    backoffAttempts, full, nextReadyCheckDelayMs, readyNodes);
737	            }
738	        }
739	
740	        // We've collected the queue sizes for partitions of this topic, now we can calculate
741	        // load stats.  NOTE: the stats are calculated in place, modifying the
742	        // queueSizes array.
743	        topicInfo.builtInPartitioner.updatePartitionLoadStats(queueSizes, partitionIds, queueSizesIndex + 1);
744	        return nextReadyCheckDelayMs;
745	    }
